INSERT INTO `oc_question` (`id`, `question`, `answer`) VALUES
(13, '     Смазки для анального секса', '     Как сделать анальный секс действительно приятным? В первую очередь, нужно обеспечить легкое проникновение и отсутствие боли. В этом хорошо помогают смазки для анального секса – они делают безумно приятным, на первый взгляд, сомнительный эксперимент. \r\nВо время анального секса использование смазки не просто желательно, а необходимо! Можно, конечно, использовать любые интимные лубриканты, но мы рекомендуем все-таки приобрести смазку, предназначенную именно для анального контакта.\r\nВ анальные смазки входят специальные компоненты, которые придают важные для анального секса свойства:\r\n•	Смазывающий эффект\r\nАнальные лубриканты обладают, как правило, более вязкой консистенцией, нежели вагинальные. Это сделано для того, чтобы обеспечить надежное скольжение там, где естественная смазка не вырабатывается. Большинство таких смазок изготовлены на основе силикона, поскольку при анальном сексе хорошее увлажнение  и длительное скольжение очень важно.\r\n Расслабляющий эффект\r\nВ состав лубрикантов для анального секса входят специальные компоненты, которые сводят к минимуму неприятные ощущения и расслабляют мышцы для удобного проникновения.\r\n  Обезболивающий эффект\r\nСнять болевой синдром помогают смазки с ментолом или другим анестетиком. Однако, при смазывании анального отверстия стоит проявлять аккуратность, так как попав на половой член или на язык смазка может вызвать потерю чувствительности .\r\nСмазки для анального секса разделяют на три категории в зависимости от основы и эффекта:\r\nТип лубриканта	Особенности применения	\r\nГель-Эти смазки способствуют более длительному скользящему эффекту, такие гель смазки могут быть либо на водной основе, либо на силиконовой основе. Для анального секса силиконовая основа более предпочтительна.	\r\nСпрей	Спреи имеют водную основу. Помогают снизить чувствительность и избавить от неприятных ощущений. Но не предназначены для создания смазывающего эффекта, поэтому их стоит использовать с анальными гелями или кремами.  	\r\nКрем	Эти смазки быстрее впитываются в мышцы ануса, тем самым помогают их расслабить. Они также имеют прекрасный скользящий эффект, так как зачастую обладают силиконовой основой.	\r\nЛубрикант  наносится непосредственно перед сексом на половые органы и/или область анального отверстия.\r\n\r\nЕсли в Вашем ящике будут такие смазки, то Вы всегда будете готовы к новому: анальный секс приносит массу удовольствия любовникам, если соблюдены все правила. Просто расслабьтесь и получайте удовольствие!\r\n     '),
(14, 'Смазки для вагинального секса', 'Комфорт в интимных отношениях - это важная составляющая нескончаемого изобилия сексуального удовольствия в те моменты, когда для гораздо больших чувственных достижений необходима дополнительная смазка. Грамотно подобранный лубрикант, уместный для конкретного случая любви, делает интимную близость комфортной, улучшая скольжение, стимулируя чувствительность и позволяя сконцентрироваться на новых интимных ощущениях от порывов сладкой страсти.\r\nСексуальные отношения должны дарить чувственность и комфорт. Но иногда естественной смазки недостаточно для безупречного скольжения. И тогда на помощь приходят вагинальные лубриканты, с которыми каждая интимная близость наполняется ласкающей нежностью ощущений. \r\n\r\nВысококачественные смазки из нашего каталога обеспечат защиту и увлажнение слизистых оболочек влагалища. Природные компоненты сохранят микрофлору и предотвратят воспаление и появление травм.\r\n  Также , чтобы создать более интимную и индивидуальную атмосферу, можно использовать смазочку с ароматом.\r\n'),
(15, 'Возбуждающие смазки', 'Возбуждающие крема и гели, вот что вам просто необходимо попробовать! Они вызывают сильное сексуальное влечение, позволяют обогатить интимную близость яркими ощущениями, эмоциями и чувствами. Гамму непередаваемых эмоций помогут ощутить стимулирующие лубриканты в составе которых  можно встретить:  имбирь, экстракт муира-пуамы и другие компоненты, которые помогут достичь более  сильного возбуждения, насыщенного оргазма и сильной эрекции. Что попробовать сначала? Решать Вам, но мы знаем точно, что Вы не пожалеете!'),
(16, ' Корректирующие размеры', ' Каждый мужчина-гигант в своих мыслях, чтобы это было и на иву, мы предлагаем специализированные крема, для увеличения мужского достоинства. Простой ряд упражнений или вакуумная помпа в сочетании с кремом, и Ваша любимая  будет просто в восторге! Также можем предложить крема которые увеличат половой член за считанные минуты.\r\nЖенщины всегда прекрасны в любом возрасте! Но эту красоту и привлекательность нужно поддерживать всегда и мы говорим не про крем для лица! Подтянуть область декольте и увеличить в размере, восстановить вагинальные мышцы после родов или просто привести в тонус, помогут эти волшебные крема.  Немного усилий и Вы королева во всех смыслах.  Не надо думать, надо брать и заказывать!\r\n '),
(17, 'Пролонгаторы.', 'Пролонгаторы, или их еще называеют «стоп» крема – это группа препаратов, увеличивающих продолжительность полового акта. Проблема преждевременной эякуляции является острой для многих мужчин. Причины появления данного симптома могут быть различными – органические и функциональные нарушения. Для симптоматического лечения отлично подходят препараты из данной группы.\r\n Их преимущество заключается в непосредственном воздействии на рецепторы, расположенные в чувствительных областях полового члена. Таким образом, чувствительность несколько снижается, что позволяет отложить момент наступления эякуляции.\r\n\r\nКрем или спрей решать тебе!\r\n Механизм действия кремов аналогичен эффекту от спреев: они также подавляют чувствительность нервных канальцев полового органа и продлевают секс в несколько раз. При этом чувствительность пениса снижается частично, а приятные ощущения от контакта не становятся менее выразительными.\r\n'),
(18, 'Съедобные смазки', 'Съедобные смазки – это настоящая феерия вкусов и фантазий!\r\nУникальные оральные съедобные смазки являются самыми желанными и популярными интимными товарми для многих пар в мире. Они не только доставят вкусовое удовольствие от процесса, но и великолепно справляются с уходом за интимными зонами, благодаря специально разработанным составам. Эти смазки являются универсальным средством не только для соблазнения, но и для возвращения в сексуальную жизнь страсти и желания.\r\n\r\n Вулкан страстей и незабываемый вкус эмоций смешались во флаконах съедобных смазок. Многие пары для орального секса используют пищевые продукты (фрукты, взбитые сливки, шоколад и т.д). Такая гастрономическая практика может нанести существенный вред чувствительной микрофлоре половых органов. Съедобные смазки не нарушают баланс микрофлоры, а сохраняют его. Они придадут вашим любовным играм особый вкус и бережно позаботятся о чувствительной интимной зоне. Подходят для использования в качестве лубриканта. Обладают увлажняющим действием. Совместимы с изделиями из латекса и синтетических материалов. \r\n'),
(19, 'Что это такое', 'Вероятно, каждый гинеколог за свою карьеру видел в своем кабинете множество женщин, которые были всерьез обеспокоены необходимостью использовать вагинальные лубриканты во время занятий сексом. Как правило, эти женщины считают, что с их телом что-то не так, или, что если бы они сильнее любили и хотели своего партнера, естественной смазки было бы более, чем достаточно. И гинекологам приходится убеждать пациенток, что применение искусственной смазки - совершенно нормальное дело.\r\nВрачи знают, что большинство женщин, независимо от возраста и репродуктивного статута, используют те или иные лубриканты или увлажняющие средства во время сексуальных контактов. Поэтому вагинальные лубриканты являются, быть может, одной из самых важных и нужных разновидностей интимной косметики.\r\n\r\nКак часто женщины испытывают неприятные ощущения при половой близости, связанные с сухостью во влагалище? Статистика утверждает, что практически каждая вторая сталкивается с этой проблемой в разные периоды своей жизни. Причем далеко не всегда это проблема женщин старшего возрастного периода. \r\n\r\nКаждая молодая женщина ощущает, что не всегда она готова к половому акту одновременно со своим партнером. Процесс возбуждения у женщин занимает гораздо больше времени, чем у мужчин и не всегда мужчины заботятся о том, чтобы довести его до конца, результатом этого становятся травмы слизистой оболочки и боли во время сексуальной жизни. Поэтому сухость во влагалище становится подчас серьезной проблемой.. \r\n\r\nЕсли вы хотите найти самую лучшую смазку для любовных игр, обязательно обратите внимание на современные лубриканты. Данные увлажнители куда эффективнее, чем обыкновенная слюна и во много раз по качеству превосходят глицерин и вазелин.\r\nНапомним, что эти устаревшие виды смазки не только оставляют некрасивые пятна на одежде, но также, что особенно важно, способны разрушать структуру латекса - а значит, для тех, кто предпочитает использовать в качестве средств контрацепции презервативы, глицерин и вазелин категорически не подходят.\r\nВсе существующие сегодня смазки-лубриканты делятся на два вида:\r\n1. На водной основе. Преимуществами данных смазок являются их универсальность и гипоаллергенность. Кроме того, они прекрасно сочетаются с презервативами, обладают приятной нелипкой консистенцией и легко наносятся. К тому же, существует огромное разнообразие подобных лубрикантов, что значительно облегчает проблему выбора.\r\n2. На силиконовой основе. Эти лубриканты прекрасно подходят для любителей долгого секса. \r\n'),
(20, 'Массажёры простаты', 'Купить стимулятор простаты можно как по назначению врача, так и в качестве секс-игрушки. Благодаря анатомически правильному наклону головки эрогенная зона подвергается направленной стимуляции. В результате вы испытаете яркий оргазм даже без орального, вагинального контакта или мастурбации. Используйте стимулятор простаты самостоятельно или доверьте свое удовольствие партнеру.\r\nМассажеры представленные в нашем магазине различны по форме, цвету и еще не мало важно по цене порадует глаз самого искушенного покупателя. Также представлены модели с вибрацией и без.\r\n'),
(21, 'Анальные стимуляторы', 'Анальные стимуляторы, выполняемые из мягкого латекса, силикона или киберскин, могут иметь различный диаметр, способствуя постепенной разработки мышечных стенок ануса. Обтекаемость форму предусматривает безболезненное введение анального стимулятора непосредственно в анус.\r\nАнальный секс является довольно щепетильной темой для девушек. Женщины побаиваются его. На самом деле в процессе такого секса у девушек часто возникают неприятные и болевые ощущения. Но это можно исправить. Анальный секс может приносить наслаждение, если к нему правильно подготовиться. Для этого необходимо делать определенные упражнения. А в этом помогут анальные пробки.\r\nЕще одним преимуществом подобного приспособления, является предварительный ввод анального стимулятора в анус, при желании заняться анальным сексом, так как он способствует правильной подготовке и расслаблению, во избежание неприятных и даже болезненных ощущений. Данная пробка является узкой у начала и более широкой у основания, которое предотвращает проваливание данного изделия в анальное отверстие. Формы и размеры этих интимных игрушек могут быть разными. Выбирать их стоит в соответствии с собственными предпочтениями.\r\nАнальные пробки могут иметь основания с липучками и даже со стразами, которые придают им эстетичности. \r\nЭти изделия могут использоваться не только для тренировок. Они подойдут и для самоудовлетворения, и для усиления ощущений во время полового акта. Так женщина может ввести себе пробку в анальное отверстие. Это сделает ее влагалище более узким. Поэтому ощущения от секса у обоих партнеров будут более яркими, чем обычно.\r\nПри этом не стоит думать, что данное изделие подходит исключительно женщинам. В профилактических целях его могут использовать и мужчины.\r\nЧтобы испытать яркие ощущения от секса, сначала необходимо подобрать изделие правильных размеров и формы.\r\nТакже нужно помнить, что анус не выделяет какую-либо смазку. Поэтому для введения в него пробки и для анального секса необходимо использовать искусственные смазки и лубриканты. Для тех, кто только начинает постигать прелести подобных половых актов подойдет смазка с обезболивающим эффектом.\r\n. Данная секс-игрушка поможет вам научиться расслаблять ее. Благодаря таким умениям вы сможете контролировать процесс анального секса и получать от него удовольствие.\r\nАнальные пробки могут быть использованы и во время вагинального секса. Если в анальном отверстии девушки будет находиться данная секс-игрушка, то ее влагалище станет уже. Это позволит обоим партнерам получить удовольствие от секса.\r\n Еще одна более популярная сексуальная игрушка  – анальная цепочка или бусы.\r\nТайские бусы – так еще называют анальную цепочку – могут служить источником дополнительного сексуального удовольствия или средством для достижения оргазма. Такая игрушка одинаково хорошо подойдет и для искушенных анальными ласками любовников, и для тех, кто только пускается в исследования.\r\nАнальная цепочка может применяться не только в качестве стимулятора, но и как подготовка к анальному сексу, чтобы растянуть и расслабить мышцы сфинктера. В таком случае следует обратить внимание на модели с шариками разного диаметра на одной цепочке. Также интересной будет цепочка с дополнительной вибростимуляцией.\r\nАнальная цепочка или анальные бусы – это шарики или бусинки, нанизанные на гибкую или жесткую основу. Шарики могут быть разного размера – от самого маленького, диаметром в 1,27 см, до самого большого в 4 см. Изготавливают цепочки из силикона, латекса, безопасной резины, пластмассы, даже из стекла. В одной цепочке могут быть шарики одинакового или разного размера, а на конце основы обычно есть удобное колечко, фиксатор или шнурок. Сами шарики могут быть с гладкой или волнистой поверхностью.\r\nКак использовать анальную цепочку?\r\n1.	Позаботьтесь, чтобы поза при введении была как можно более расслабленной и комфортной: можно подложить под поясницу подушку, ягодицы должны быть расслаблены.\r\n2.	Чтобы избежать травм, необходимо использовать дополнительные средства: не забудьте смазку на силиконовой или водной основе, в зависимости от материала бус. Наносить смазку рекомендуется на бусы и на стенки ануса.\r\n3.	Не стоит торопиться! Вводите шарики постепенно, медленными и аккуратными движениями.\r\n4.	Удобнее всего применять цепочку для парных игр – анальная стимуляция одинаково приятна как женщинам, так и мужчинам. В первом случае она позволяет получить более яркий маточный оргазм, во втором – дополнительное удовольствие от стимуляции простаты.\r\n5.	На конце цепочки оснащены удобными колечками или шнурками, не позволяющими им полностью провалиться в анус. Если такового нет, тщательно следите за количеством введенных шариков.\r\n6.	Вынимать цепочку можно как во время оргазма с целью его усиления, так и до, и после него. Это зависит от ваших предпочтений. Экспериментируйте!\r\nТакже все анальные стимуляторы могут быть в вибрацией, что быстрее позволит достичь желаемого эффекта!\r\n'),
(22, 'Бельё', 'Белье - это душа женщины, оно отражает ее мысли и настроения. Оно обладает притягательной силой, неподвластной времени. Женское белье вызывало восхищение всегда и везде, во все времена и у всех народов. Оно много говорит о женщине, которая его носит, и мужчины стараются всматриваться в него как можно внимательнее. \r\nУже давно белье перестало выполнять исключительно практическую, гигиеническую функцию – ее основной задачей стало подчеркнуть сексуальную привлекательность женщины.\r\n Женщине при этом недостаточно, чтобы ее сексуальность была признана противоположным полом, гораздо важнее, чтобы сама женщина чувствовала себя королевой. Несомненно оценивая при выборе нижнее белье с той точки зрения насколько оно понравится любимому мужчине, в большей степени женщина выбирает белье для себя – ей важно самой чувствовать себя в нем великолепной, неотразимой, сексуальной.\r\n'),
(23, 'Вагинальные шарики.', 'В реальности, вагинальные шарики представляют собой полноценный влагалищный тренажер, помогающий решить массу проблем с психологическим и физическим сексуальным здоровьем. Какие именно? Судите сами:\r\n-Влагалищные мышцы скорее реабилитируются после перенесенных родов;\r\n-У половых органов повышается чувствительность; \r\n-Шарики во влагалище – это источник невероятно яркого и запоминающегося оргазма; \r\nТренажеры помогают избежать возрастных гинекологических и урологических патологий, таких как: выпадение маточной шейки и самого детородного органа, непроизвольное испускание мочи и т.д.\r\nВагинальные шарики, созданные для тренировки мышц, представляют собой две (реже более) последовательно связанные сферы, изготовленные из латекса, резины, пластика и даже металла или древесины. Внутри оргазменных мячиков подвешены железные грузики, колеблющиеся при малейшем движении. В нашем магазине присутствуют шарики со смещенным центром тяжести, утяжеленные, совершенно гладкие или с эффектом шершавости. Кроме этого, для тренировки влагалищных мышц можно использовать яйцеобразные аксессуары этого типа, которые используются поодиночке, а не связанными парами, имеют большие размеры, чем стандартные вагинальные сферы, и часто оснащаются эффектом вибрации. Последний помогает получить максимальное удовлетворение от процесса применения, и усиливает позитивный результат от тренировки.\r\n\r\nВ данном случае принимайте во внимание следующие моменты:\r\n Для начала попробуйте купить и удержать мышцами влагалища мячики стандартного типа, или со смещенным центром тяжести; \r\nЕсли вы никогда не пользовались подобными игрушками, не покупайте слишком маленькие или чрезмерно тяжелые шарики; \r\nАбсолютно гладкие, маленькие и тяжелые аксессуары потребуют от вас предельного напряжения мышц. Ими трудно управлять, но эффект получается самый наилучший; \r\nОпять же, если есть необходимость быстро восстановить мышечный тонус влагалища, или во время полового акта вы неспособны полностью обхватить член своего партнера, то выбор нужно остановить на самых крупных  сферах со смещенным центром тяжести.\r\n\r\nПОРЯДОК ВЫПОЛНЕНИЯ УПРАЖНЕНИЙ \r\nТеперь непосредственно о том, как пользоваться вагинальными шариками. Запомните: весь сеанс массажа выполняется только в положении стоя. Заранее расслабьте мышцы вагины, смажьте игрушку специальным средством, и только потом начинайте вводить. После того как сферы окажутся во влагалище, попробуйте максимально сильно обхватить их мышцами, ощутить их форму, тяжесть и степень шероховатости. Затем в мыслях разделите вагину на три отдела, и по очереди прорабатывайте каждый из них. В принципе, не существует четко прописанных упражнений, важно отдаться во власть ощущений, по очереди и с разной силой сжимать и разжимать сферы, чувствовать и сокращать каждый отдел влагалища. Научившись элементарным манипуляциям с шариками, можно переходить к более сложным тренировкам, в которых буду задействованы интимные игрушки минимальных размеров, совершенно гладкие или ощутимо тяжелые.\r\n'),
(24, 'Вагины и мустурбаторы', 'Получать сексуальную разрядку очень важно для мужского здоровья, но регулярный секс не всегда возможен. Помочь в таком случаем может мастурбация, а купив в секс шопе искусственную вагину или мастурбатор, можно достичь максимально реальных ощущений. Можно выбрать мастурбатор в виде ротика, вагины или ануса, разных цветов и из разнообразных материалов, с вибрацией для дополнительной стимуляции и без нее.\r\nИмитаторы женских половых органов отличаются формой, материалом,  (чаще всего это латекс, силикон, киберсиликон и другие подобные материалы), наличием вибратора. \r\nПо всей внутренней длине вагины располагаются всевозможные мягкие шишечки-возбудители. Они оказывают активное массажное воздействие на пенис во время использования вагины. Кроме того, массажный эффект достигается благодаря вибрации (при наличии специального устройства). Вне зависимости от модели, вагина плотно обхватывает половой член. Благодаря этому у мужчины возникают ощущения, подобные тем, что возникают при близости с молоденькой девушкой.'),
(25, 'Вибратор', 'электромеханическое изделие, предназначенное для массажа вагины, или анального отверстия. Соответственно, различаются четыре вида вибраторов: клиторальные, вагинальные и анальные, а также комбинированные. Часто имеет вид полового члена.\r\nВагинальные вибро-стимуляторы - приборы для стимуляции вагинальных эрогенных зон с вибраторами на батарейках, в т.ч. обычные вибраторы в виде фаллоса, вибраторы для стимуляции клитора, а так же специальные вибраторы для стимуляции &quot;точки G&quot;. \r\nКлиторальный стимулятор – мини-вибратор, предназначенный для стимуляции клиторальной зоны. Клиторальные стимуляторы могут быть с выносным или встроенным пультом управления. Изделие может обладать специальными приспособлениями для закрепления его в области клитора (это могут быть либо резиночки, либо специальные трусики). Вне зависимости от сложности изделия, его формы и размера все клиторальные стимуляторы исполняют роль своеобразных тренажёров. Симпатичные гелевые или киберскиновые зайчики, мишки, мотыльки и бабочки готовы затрепетать под воздействием мини-помощников – маленьких вибраторов, встроенных в их нежные тельца, и подарить вам точечную вибрацию или пульсацию, сила и степень воздействия которых полностью подвластны вашему желанию. \r\nВибраторы точки G \r\n К сожалению, для многих женщин точка G остается неизведанной зоной, практически каким-то мифом современной жизни. И это в наш век просвещения и общедоступности любого рода информации. Объяснение этого удивительного факта заключается в том, что теоретическая подкованность в этом вопросе - это фундамент, но дальше него без практики уйти невозможно. Самая таинственная и чувствительная эрогенная зона женщины – это, конечно же, точка G. В силу своих анатомических особенностей, не каждый мужчина способен стимулировать эту точку во время полового акта. В отличие от полового члена, вибраторы точки G (джи) имеют особую форму с загнутой головкой, которая осуществляет направленную стимуляцию самой главной эрогенной зоны женщины, поэтому получить незабываемый оргазм с помощью специального вибратора не составит труда. \r\nАнальные вибраторы см. анальные стимуляторы.\r\nВибраторы с двойной стимуляцией, представляют собой вагинальный вибратор с отростком для стимуляции клитора, либо вагинальный вибратор с отростком для анальной стимуляции.\r\n'),
(26, 'Кукла', 'Заказать реалистичную надувную секс куклу для мужчин осмелится не каждый. Очень часто такую секс-игрушку преподносят в подарок мужчине «без комплексов». Однако если вы сами решитесь на подобное приобретение – поверьте, вы не останетесь разочарованы. \r\nПри постоянном или временном отсутствии сексуального партнера можно использовать эротические куклы для секса, которые точно воспроизводят тело человека. Рост таких кукол составляет от полутора метров с точной или приблизительной имитацией половых органов. Надувные девушки помогают преодолевать комплексы, которые проявляются у некоторых людей в интимной жизни с партнером, получая при этом сексуальную разрядку. Также в современном мире уже не удивят и надувные куклы для женщин.\r\n'),
(27, 'Массажное масло', 'Нет ничего желаннее прикосновений любимых рук! Для того чтобы научиться делать эротический массаж, не нужно быть дипломированным массажистом. Здесь нет никаких запретов и жестких правил, кроме одного — получить взаимное удовольствие. Мы расскажем об универсальных приемах такого массажа.\r\nПоднимись над суетой\r\n1. Основное правило — забудьте о времени. Забудьте обо всем, что не касается этого конкретного момента, что не относится к &quot;здесь&quot; и &quot;сейчас&quot;. Никакого негатива — иначе ваши руки мгновенно передадут его любимому человеку, и изысканное удовольствие превратится в изощренную пытку. Позаботьтесь о комфортной обстановке — приветствуется приглушенный свет и, по желанию, негромкая музыка как фон. Отлично подойдет музыка для медитации.\r\n2. Позаботьтесь о комфортной температуре в помещении, чтобы она была не ниже 24—25 градусов. \r\n3. Массажное масло выбирайте без резкого запаха. Возбуждающими считаются масла иланг-иланга, пачули, сандала. Однако если вы не уверены, что этот аромат понравится, выберите что-нибудь нейтральное — например, аромат клубники, персика, ванили.Опустите емкость с маслом в горячую воду на несколько минут, чтобы оно согрелось до температуры тела, а когда будете его наносить — не экономьте.\r\n4. Разговоры не приветствуются — пусть за вас говорят прикосновения.\r\n5. Приступив к массажу, не допускайте пауз, даже незначительных. В этом состоит секрет техники так называемого обволакивающего массажа. \r\n6. В эротическом массаже в принципе используются те же приемы, что и в обычном: поглаживания, растирания, разминания, вибрации, только все движения выполняются плавно и нежно. Никакой грубости или применения силы — разве что ваш партнер сам не попросит об этом. Движения должны быть ритмичными: чтобы понять, какой ритм правильный, следите за реакцией.\r\n7. Чем легче прикосновения, тем острее реакция нервных окончаний. Особенно чувствительна к невесомым поглаживаниям кожа внутренней поверхности бедер и рук, затылка, а также кожа под коленями и в области гениталий. Ритмичное прикосновение раскрытых ладоней, когда одна рука сменяет другую, создает ощущение прикосновения множества рук. Особенно возбуждающе это действует при массаже рук и ступней. Отличие эротического массажа от классического еще и в том, что его можно выполнять на передней поверхности тела, включая живот и половые органы.\r\n8. Такой массаж может быть прелюдией к сексу, но это вовсе необязательно. \r\nВ этот момент близости Вам не обойтись без хорошего массажного масла.\r\n\r\n'),
(28, 'Наборы', 'Наш интернет-магазин готов с радостью представить Вашему вниманию наборы, которые будут  отличным подарком, а если же Вы захотите их приобрести для себя, Вы убьете всех зайцев одним ударом. В большинстве случаев в них представлен вибратор, насадки которые можно надеть на вибратор или на половой член, эрекционные кольца для мужчин, анальные стимуляторы и в некоторых случаях вагинальные шарики. Материал из которого изготовлен набор  может быть различен: силикон, пластик, киберскин. Покупая такую продукцию, Вы сможете удовлетворить себя и партнера во всех смыслах.'),
(29, 'Насадки и кольца', 'Если ваше семейное ложе превратилось в трассу для скоростных рекордов, это рано или поздно послужит причиной разладов в семье. Кольца и насадки на пенис пользуются большой популярностью у пар, стремящихся увеличить продолжительность и качество интимного акта. Эти небольшие аксессуары позволяют продлить сексуальную симфонию до получаса, даже если вы испытываете затруднения с эрекцией или стремительно финишируете на фоне сильного возбуждения.\r\nКак использовать эрекционное кольцо\r\nЭрекционное колечко фиксируется на основании эрегированного полового члена и контролирует отток крови, удерживая стойкую эрекцию продолжительное время (до получаса). Таким образом, вы можете забыть о проблемах из-за слабовыраженной эрекции и сосредоточиться на акте любви – ваш Биг-Бен всегда будет показывать полночь.\r\nАссортимент эрекционных колец и насадок\r\nВ нашем интернет-магазине  представлены кольца и насадки на пенис в широком ценовом диапазоне отличного качества от ведущих производителей. Мы предлагаем:\r\n•	регулируемые и фиксированные по размеру модели из комфортных безопасных материалов;\r\n•	с вибрирующим элементом, которые не только поддерживают долговременную эрекцию, но и оказывают дополнительную стимуляцию эрогенных зон обоих партнеров;\r\n•	вибронасадки с интенсивной вибрацией, продлевающие эрекцию и усиливающие ощущения обоих партнеров.\r\n•	модели, предусматривающие стимуляцию простаты;\r\n•	реалистик насадки из киберкожи.\r\n•	Закрытые насадки, которые помогут увеличить половой член в размере.\r\n•	Также,  насадки, которые будут активно стимулировать партнершу где головка полового члена будет открыта.\r\n'),
(30, 'О нам и про магазин', 'Как спастись от рутины и внести новые яркие моменты в свою интимную жизнь, добиться новых вершин наслаждения? Ели тебя посещали подобные мысли, значит, пора в интим-магазин.\r\nХотим вам рассказать о пользе интим товаров, представленных в нашем магазине. Мы надеемся, что использование тех или иных средств, сделает ваши сексуальные отношения более красочными, яркими, активными и захватывающими. Вы сможете окунуться в мир ваших тайных желаний!\r\nВ нашем интим магазине вас ожидает богатый выбор всего того, что помогает сделать занятия любовью еще прекраснее и восхитительнее: фаллоимитаторы, вибраторы, шарики, кремы и капли для усиления ощущений и возбуждения, а также эротическое нижнее белье. Эти средства позволяют получить максимальное удовольствие от собственного тела. \r\nПроведенные статистические исследования показывают, что теми средствами, которые представлены в нашем интим магазине, пользуется приблизительно половина взрослых, сексуально активных людей. Многие представленные средства совершенствуют акт и придают отношениям абсолютно новый и еще неизведанный оттенок, некоторые служат для медицинских целей. Но самое главное предназначение наших товаров - открыть для вас новый мир сексуальных фантазий! \r\nИ как бы многие не хмурили бровь по поводу секс-магазина, товары, купленые там, предоставят тебе возможность разнообразить интимную жизнь. Именно секс-игрушки, возможную роль которых, зачастую, просто отбрасывают, мотивируя тем, что в постели и без этого все замечательно. Но именно они – возможность познания новых границ наслаждения, возможность дарить себе и своему партнеру яркие, незабываемые ощущения. Использование игрушек сексуального характера возможно как в неком акценте сексуальной игры, так и в непосредственном контакте с партнером.\r\nАдам и Ева – мир ваших тайных желаний!\r\n'),
(31, 'Помпы', 'Вакуумная помпа для мужчин на данный момент является эффективным средством для увеличения мужского полового органа и улучшения его работы. Производители гарантируют быстрый эффект и стойкий результат. Различают электрические и ручные вакуумные помпы. Ручной вариант — это цилиндр диаметром 7 см и длиной около 20 см. К нему прикрепляется ручной насос, который откачивает воздух из цилиндрической емкости. Такая помпа в основном выполнена из пластика акрилита. А вот вакуум в электрических приборах образуется при помощи электронасоса, который равномерно откачивает воздух. Некоторые модели оснащены специальной кнопкой, регулирующей интенсивность создания вакуума в цилиндре. Итак, действие помпы основывается на создании вакуума внутри прибора, в котором находится половой член. В результате понижения и повышения давления активизируется кровообращение в члене, благодаря чему он становится длиннее и толще, чем при обычной эрекции.Регистрация/Вход \r\nВакуумный тренажер для женщин не столь распространен, как мужской. Но все же секс-индустрия предлагает помпы и для женщин. Давайте же разберемся в том, какие помпы существуют, постараемся выявить особенности и пользу применения.\r\nПомпа для груди и сосков\r\nТакой тренажер признается однозначно полезным при недостаточном тонусе кожи груди и плоских сосках. Его применение позволяет добиться значительного эффекта: грудь становится более упругой, кожа подтягивается, а соски становятся выпуклыми и легко эрегируют при прикосновении. Грудь приобретает высокую чувствительность и красивую форму.\r\nПомпа для половых губ и клитора\r\nИзначально помпа создавалась как тренажер для профилактики застойных заболеваний органов малого таза. Сегодня — это необычный способ привнести в сексуальную жизнь новые нотки.\r\nПо аналогии с мужским тренажером, женская помпа призвана увеличить приток крови к половым органам и повысить чувствительность. Пластиковая чаша прижимается к области вагины, с помощью груши в ней создается вакуум. При проведении нескольких процедур «вакуум-воздух» большие и малые губы женщины, а также клитор значительно увеличиваются в размерах. Их чувствительность сильно повышается. Внешний вид женских половых органов после использования помпы многие мужчины считают более возбуждающим.\r\nТакой массаж имеет несомненную пользу: при регулярном его проведении женщина становится более чувствительной, быстрее достигает оргазма. Оргазмы становятся ярче и продолжительнее. Кроме того, можно купить помпы, которые оснащены встроенными вибраторами. Сочетание вакуумного массажа и воздействия вибратора дарит ни с чем несравнимые сексуальные переживания.\r\nОднако здесь стоит соблюдать осторожность и не увеличивать время воздействия вакуума выше указанного в инструкции. Злоупотребление помпой может привести к отеку, гиперемии и подкожным кровоизлияниям, в то время как умеренное использование принесет только приятные эмоции, усилит возбуждение и сделает секс незабываемым.\r\n'),
(32, 'Презервативы', 'В наше время презервативы, это не только средство защиты от преждевременной беременности, но и возможность разнообразить свою интимную жизнь! Точечные, ребристые, с шариками, с усиками, ультратонкие, ароматизированные, с продлевающим эффектом,  решать только тебе, что ты захочешь сегодня!'),
(33, 'Страпоны и фаллопротезы', 'Страпоны и фаллопротезы представляют собой уникальную секс игрушку, состоящую из трусиков или ремешков и насадки фаллоимитатора. Однако по своей конструкции они делятся на мужские и женские. \r\nМужские модели чаще всего называют фаллопротезами, так как в большинстве из них предусмотрено отверстие для помещения полового органа со слабой эрекцией. \r\nЖенские модели помогут очаровательной представительнице женского пола испытать наслаждение от главенствующей роли в паре. При этом ее партнером может быть как мужчина, так и другая женщина. Некоторые модели страпонов и фаллопротезов снабжены дополнительными насадками, направленными на стимуляцию клитора, влагалища и ануса самой партнерши. \r\nСуществуют также мужские страпоны, которые позволяют осуществить потаенную мечту практически каждой женщины о двойном проникновении, не приглашая в постель посторонних. Эти интимные игрушки помогут приятно разнообразить и усовершенствовать интимную жизнь абсолютно любой паре.  \r\n Стоит также отметить, что страпоны отличаются друг от друга размерами, формой, количеством насадок и материалом, использованным при изготовлении. Благодаря этому многообразию найти идеальный вариант и купить страпон по своему вкусу удастся абсолютно любой паре, вне зависимости от их половой принадлежности, возраста и стажа интимной жизни.\r\nПомните, заботясь о качестве своей интимной жизни, вы сохраняете любовь!\r\nНи одному партнеру или партнерше не придет в голову искать приключения на стороне, если их сексуальная жизнь разнообразна и полна впечатлений!\r\n'),
(34, 'Фаллоимитатор', 'это аналог полового члена. Он может точно повторять вид пениса, а может лишь отдаленно напоминать его. Вне зависимости от сложности изделия, все имитаторы исполняют роль своеобразных тренажеров, манипуляции с которыми позволяют изучить собственные сексуальные реакции, реализовать фантазии, использовать их в сексуальных играх с партнером как для вагинального, так и для анального секса. Фаллоимитаторы из различных материалов, это силикон и латекс, акрил и пластик, дерево и металл, камень и стекло. Самые распространенные фаллоимитаторы выполненные из силикона, самые реалистичные — из латекса. Следует выделить двойной фаллоимитатор, который способен доставить женщине несравнимое удовольствие, осуществляя двойное проникновение.\r\n Конечно, фаллоимитатор, какой бы он ни был, - это всего лишь игрушка, и он никогда не вытеснит теплых человеческих взаимоотношений, но помочь решить многие сексуальные проблемы он может. Поэтому не стоит себе отказывать в том, что укрепит или наладит когда-то возникшую связь между двумя людьми. Ведь все это придумано во имя любви.\r\n');
